import{_ as s,o as t,c as e,ag as n}from"./chunks/framework.C9sp7nFj.js";const u=JSON.parse('{"title":"AutoGainEnable 开启伺服自调节","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/AutoGainEnable.md","filePath":"3. 指令/5. 设置指令/AutoGainEnable.md","lastUpdated":1778862643000}'),i={name:"3. 指令/5. 设置指令/AutoGainEnable.md"};function r(l,a,o,h,d,p){return t(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="autogainenable-开启伺服自调节" tabindex="-1">AutoGainEnable 开启伺服自调节 <a class="header-anchor" href="#autogainenable-开启伺服自调节" aria-label="Permalink to &quot;AutoGainEnable 开启伺服自调节&quot;">​</a></h1><p>该指令用于<strong>开启伺服参数自调节功能</strong>。在机器人运行过程中，高低速切换时对伺服增益的需求不同。执行此指令后，系统会监控各关节的实时速度，一旦速度低于设定的阈值，便会自动调整增益比例，从而<strong>优化机器人在低速段的运动表现</strong>（如消除低速爬行、震动或提升停点精度）。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>AutoGainEnable(LsScaleP, LsThreshP) AutoGainEnable(低速增益比例变量, 低速速度阈值变量)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>LsScaleP：低速段增益比例 (LsScale)</td><td>LsScale 类型变量（结构化变量，包含各轴参数）</td><td>定义当关节进入低速状态时，伺服增益提升或调整的比例系数。较高的增益可以增强低速下的刚性，使动作更精准。</td><td></td></tr><tr><td>LsThreshP：低速段速度阈值 (LsThresh)</td><td>LsThresh 类型变量（结构化变量，包含各轴参数）</td><td>定义&quot;低速段&quot;的界限。当关节轴的实时速度低于此变量中设定的值时，系统判定进入低速段并激活增益调节。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>伺服控制中存在一个矛盾：高速时需要较低的增益以避免高频振荡，而低速或停止时需要较高的增益以保证定位精度。<code>AutoGainEnable</code> 通过动态切换，实现了&quot;高速稳、低速准&quot;。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 假设 LsScale0 设定了增益提升 1.2 倍，LsThresh0 设定阈值为 5% 额定速度 */</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AutoGainEnable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(LsScale0, LsThresh0)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>执行结果：</strong></p><p>伺服自调节功能开启。在向 <strong>P1</strong> 运动的过程中，特别是在接近终点的减速阶段，当速度降至 <strong>LsThresh0</strong> 以下时，系统会自动应用 <strong>LsScale0</strong> 的增益补偿，确保机器人平稳、精确地停在目标位置，不发生微小晃动。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>精密装配/涂胶</strong>：在轨迹末端或拐角处速度较低时，开启自调节可防止因摩擦力导致的&quot;顿挫&quot;或&quot;爬行&quot;现象。</li><li><strong>高负载定位</strong>：搬运重物时，低速阶段的惯性影响显著，通过自调节增加增益可以更好地控制重物的停准位。</li><li><strong>抑振优化</strong>：如果机器人低速运行时存在明显的低频抖动，可以通过此指令配置合适的低速参数进行消除。</li></ul><hr><blockquote><p><strong>提示：</strong> 该功能属于高级伺服调优范畴。通常情况下，<code>LsScale</code> 和 <code>LsThresh</code> 的具体数值需要根据具体的机械刚性和负载情况进行测试或由官方技术人员指导设定。</p></blockquote>`,20)])])}const k=s(i,[["render",r]]);export{u as __pageData,k as default};
